#!/usr/bin/env node
/**
 * Emits dist/nginx-redirects.conf as real 301s.
 *
 * Astro's built-in `redirects` produce meta-refresh HTML pages in static
 * output. Those pass equity poorly, so astro.config.mjs applies the map in
 * dev only (for parity while developing) and nginx does the real work in
 * production. assert-urls.mjs fails the build if a meta-refresh page ever
 * reaches dist/.
 *
 * Paste the output into Plesk's Apache & nginx Settings for the domain, under
 * "Additional nginx directives", or include it from a file. Regenerated by CI
 * on every build, so it never drifts from the map.
 */
import { writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { patternRedirects, redirectList, validateRedirects } from '../src/lib/redirects.mjs'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const OUT = join(ROOT, 'dist', 'nginx-redirects.conf')

const errors = validateRedirects()
if (errors.length) {
  console.error('FAIL: refusing to generate rules from an invalid map:')
  for (const e of errors) console.error(`    ${e}`)
  process.exit(1)
}

/** nginx `location =` is an exact match, so no regex escaping is needed and
 *  no rule can accidentally catch a longer path. */
const rules = redirectList
  .map(
    (r) =>
      `location = ${r.source} {\n    return 301 ${r.destination};\n}`,
  )
  .join('\n\n')

/* Regex rules, written last in the file for readability. Position in the file
   does not decide precedence: nginx tries every `location =` before any regex
   location, whatever order they appear in, so an exact rule above always wins
   over a pattern here. */
const patterns = patternRedirects
  .map(
    (r) =>
      `location ~ ${r.pattern} {\n    return 301 ${r.destination};\n}`,
  )
  .join('\n\n')

const header = `# Generated by scripts/generate-nginx-redirects.mjs. Do not edit by hand.
# Source of truth: src/lib/redirects.mjs
# Generated: ${new Date().toISOString()}
# Entries: ${redirectList.length} exact, ${patternRedirects.length} pattern
#
# Real 301s. Astro's built-in redirects emit meta-refresh pages instead,
# which pass equity poorly, so they are applied in dev only.
#
# These must be evaluated BEFORE the trailing-slash rewrite in
# docs/DEPLOYMENT.md, because every source here already ends in a slash.
`

if (!existsSync(dirname(OUT))) mkdirSync(dirname(OUT), { recursive: true })
writeFileSync(OUT, `${header}\n${rules}\n\n${patterns}\n`)

console.log('--- generate-nginx-redirects ---')
console.log(
  `wrote ${redirectList.length} exact + ${patternRedirects.length} pattern ` +
    'rule(s) -> dist/nginx-redirects.conf',
)
